/**
 * Built-in starter catalog.
 *
 * Read-only, shared by every therapist. A therapist copies entries into their own
 * library (POST /therapist/exercise-catalog/import); the copy remembers its `key`
 * as `Exercise.catalogKey` and can then be edited freely like any other exercise.
 *
 * Content is general, non-diagnostic starter material. Keys are stable identifiers:
 * never rename or reuse a key, only add new ones.
 */
import type { Difficulty } from '@prisma/client';

export type CatalogExercise = {
  key: string;
  title: string;
  description: string;
  instructions: string;
  safetyNotes: string;
  bodyPart: string;
  difficulty: Difficulty;
  sets: number;
  reps: number;
  durationSeconds: number;
};

